"""Parser for Terminus2 agent trajectories."""

import json
import re
from typing import List, Dict, Any
from .base_parser import BaseTrajectoryParser, TrajectoryStep, ActionKind
from .file_events import command_cwd, output_views, terminal_events_with_outcome


class TerminusParser(BaseTrajectoryParser):
    """Parses episode-based trajectories generated by Terminus2."""

    _OBJECT_RE = re.compile(r"\{.*\}", re.S)
    # The shell prompt ends each capture and names the working directory.
    _PROMPT_CWD_RE = re.compile(r"(?m)^[^\s@]+@[^\s:]+:(/[^\s#$]*|~[^\s#$]*)\s?[#$]")

    def _prompt_cwd(self, text: str):
        """The working directory in the last shell prompt shown, or None."""
        found = self._PROMPT_CWD_RE.findall(text or "")
        return found[-1] if found and found[-1].startswith("/") else None

    def _keystrokes(self, response: str) -> str:
        """The shell text a Terminus2 response typed, one command per line.

        A response is a JSON object whose `commands` carry the raw keystrokes
        sent to the terminal. Scanning the response itself reads the
        `analysis` prose instead of the commands, which is why no read was ever
        detected and why a sentence containing `>` could count as a write.
        """
        data = None
        for text in (response, (self._OBJECT_RE.search(response or "") or [None])[0]):
            if not text:
                continue
            try:
                data = json.loads(text)
                break
            except (ValueError, TypeError):
                continue
        if not isinstance(data, dict):
            return ""
        commands = data.get("commands") or []
        return "\n".join(str(c.get("keystrokes", "")).rstrip("\n")
                         for c in commands if isinstance(c, dict))

    def parse_trajectory(self, raw_data: Any, manifest_item: Dict[str, Any]) -> List[TrajectoryStep]:
        if not raw_data:
            return []

        episodes = []
        if isinstance(raw_data, dict) and "episodes" in raw_data:
            episodes = raw_data.get("episodes") or []
        elif isinstance(raw_data, list):
            episodes = raw_data

        if not episodes:
            return []

        steps: List[TrajectoryStep] = []
        manifest_item = manifest_item or {}
        incorrect_steps = set()
        unuseful_steps = set()
        for stage in manifest_item.get("incorrect_stages", []):
            incorrect_steps.update(stage.get("incorrect_step_ids", []))
            unuseful_steps.update(stage.get("unuseful_step_ids", []))

        scripts: Dict[str, str] = {}
        for idx, ep in enumerate(episodes, start=1):
            action_raw = ep.get("response", "") or ep.get("action", "")
            # The published episodes carry prompt/response/debug only: what an
            # episode's keystrokes printed is the "New Terminal Output" at the
            # start of the next episode's prompt. Reading a missing
            # `observation` field left every Terminus2 step with no output, so
            # nothing it printed ever counted as the agent seeing a file.
            obs_raw = ep.get("observation", "") or ep.get("output", "")
            if not obs_raw and idx < len(episodes):
                obs_raw = episodes[idx].get("prompt", "") or ""

            typed = self._keystrokes(action_raw)
            if typed:
                kind, reads, writes = self.extract_bash_file_operations(typed)
            else:
                kind, reads, writes = ActionKind.UNKNOWN, [], []
            # The terminal's output arrives in the next episode's prompt with no
            # exit status; a write fails only where the terminal names it.
            # A tmux shell persists: the episode starts where the last prompt
            # it was shown says the shell is.
            cwd = self._prompt_cwd(ep.get("prompt", "") or "")
            events = terminal_events_with_outcome(typed, obs_raw, cwd=cwd, scripts=scripts) if typed else []

            step = TrajectoryStep(
                step_id=idx,
                action_raw=action_raw,
                action_kind=kind,
                target_files_read=reads,
                target_files_written=writes,
                observation_raw=obs_raw,
                is_incorrect=(idx in incorrect_steps),
                is_unuseful=(idx in unuseful_steps),
                token_count_estimate=self.estimate_tokens(action_raw + obs_raw),
                metadata={"framework": "Terminus2", "episode": idx},
                events=events,
                output_reads=output_views(obs_raw, cwd=self._prompt_cwd(obs_raw) or command_cwd(typed, cwd)),
            )
            steps.append(step)

        return self.canonicalize_paths(steps, manifest_item)
